package br.com.agenciafenixwarriors.liveai;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;import org.json.JSONObject;import java.util.concurrent.Executors;
public class MainActivity extends Activity{private final SupabaseApi api=new SupabaseApi();private final java.util.concurrent.ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout root;@Override public void onCreate(Bundle b){super.onCreate(b);showLogin();}private TextView title(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(sp);v.setPadding(0,14,0,14);return v;}private EditText input(String hint,boolean pass){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(0xFF888888);e.setBackgroundColor(0xFF1A1A1E);e.setPadding(20,18,20,18);if(pass)e.setInputType(0x81);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);e.setLayoutParams(p);return e;}private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);return b;}private void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,36,28,28);root.setBackgroundColor(0xFF0B0B0D);ScrollView s=new ScrollView(this);s.addView(root);setContentView(s);}private void showLogin(){base();root.addView(title("🐦‍🔥 FÊNIX LIVE AI",28));root.addView(title("Acesso exclusivo para usuários autorizados",15));EditText email=input("E-mail",false),pass=input("Senha",true);root.addView(email);root.addView(pass);Button login=button("Entrar");root.addView(login);TextView status=title("",14);root.addView(status);login.setOnClickListener(v->{login.setEnabled(false);status.setText("Validando acesso...");io.execute(()->{try{api.signIn(email.getText().toString().trim(),pass.getText().toString());JSONObject p=api.getMyProfile();api.getFeatureFlags();runOnUiThread(()->showDashboard(p));}catch(Exception e){runOnUiThread(()->{status.setText("Acesso negado: "+e.getMessage());login.setEnabled(true);});}});});}private void showDashboard(JSONObject p){base();root.addView(title("FÊNIX LIVE AI",28));root.addView(title("Olá, "+p.optString("full_name")+" • BIGO ID: "+p.optString("bigo_id"),14));TextView score=title("FÊNIX SCORE — pronto para iniciar",20);root.addView(score);Button start=button("▶ INICIAR LIVE + COACH");root.addView(start);Button coach=button("🧠 Estratégia agora");root.addView(coach);Button tele=button("📝 Teleprompter");root.addView(tele);Button goals=button("🎯 Metas");root.addView(goals);Button stars=button("⭐ Stars");root.addView(stars);Button pk=button("⚔️ Coach de PK");root.addView(pk);TextView advice=title("O Coach exibirá recomendações durante a live.",16);root.addView(advice);coach.setOnClickListener(v->{advice.setText(CoachEngine.advise(15,4,0,2,0,0,0,0));score.setText("FÊNIX SCORE: "+CoachEngine.score(15,4,0,2,0,0)+"/100");});start.setOnClickListener(v->startOverlayAndBigo());tele.setOnClickListener(v->toast("Teleprompter integrado ao botão flutuante no MVP."));goals.setOnClickListener(v->toast("Metas de Beans serão acompanhadas durante a sessão."));stars.setOnClickListener(v->toast("Coach de Stars ativo no MVP."));pk.setOnClickListener(v->toast("Coach de PK ativo no MVP."));}private void startOverlayAndBigo(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));toast("Autorize 'Exibir sobre outros apps' e toque novamente em INICIAR LIVE.");return;}Intent s=new Intent(this,OverlayService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(s);else startService(s);Intent bigo=getPackageManager().getLaunchIntentForPackage("sg.bigo.live");if(bigo!=null){bigo.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(bigo);}else toast("BIGO LIVE não encontrado neste aparelho.");}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
